riskRegisterView=async()=>{const [base,readiness]=await Promise.all([riskRegisterBackupView(),api('/api/restore-readiness?limit=100')]);return base+restoreReadinessPanel(readiness);};
function incidentRecoveryPanel(d){const evidence=phase=>phase.evidence_refs.map(h).join(' · ')||tr('لا دليل','No evidence');return `<div class="divider"></div><section class="panel"><div class="panel-head"><h2>${tr('سير عمل التعافي من الحوادث','Incident recovery workflows')}</h2></div><div class="panel-body"><div class="hint">${h(d.claim)}</div>${table([tr('سير العمل والحادث','Workflow / incident'),tr('الاحتواء','Containment'),tr('استرداد الهوية والتكوين والأجهزة','Identity / configuration / device recovery'),tr('التحقق من آثار التهديد','Threat clearance'),tr('إعادة الاتصال','Reconnection'),tr('الدليل','Evidence')],d.items.map(item=>[`${h(item.recovery_id)}<div class="secondary mono">${h(item.incident_ref)} · ${h(item.asset.hostname||item.asset.external_id)}</div>${pill(item.workflow_state)}`,`${pill(item.containment.status)}<div class="secondary">${evidence(item.containment)}</div>`,`${pill(item.identity_recovery.status)} ${pill(item.configuration_recovery.status)} ${pill(item.device_recovery.status)}<div class="secondary">${evidence(item.identity_recovery)} · ${evidence(item.configuration_recovery)} · ${evidence(item.device_recovery)}</div>`,`${pill(item.threat_clearance.status)}<div class="secondary">${item.threat_clearance.findings_remaining} ${tr('أثر متبقٍ','remaining findings')} · ${evidence(item.threat_clearance)}</div>`,`${pill(item.reconnection.status)}<div class="secondary">${h(item.reconnection.approved_by||tr('لا موافقة','No approval'))}${item.reconnection.approved_at?` · ${h(date(item.reconnection.approved_at))}`:''}</div>`,`${evidence(item.reconnection)}<br>${button('event',tr('دليل سير التعافي','Recovery-workflow evidence'),item.event_id,'text-button')}`]),tr('لا توجد سجلات تعافٍ','No incident-recovery records'),d)}</div></section>`;}
const riskRegisterReadinessView=riskRegisterView;
riskRegisterView=async()=>{const [base,recovery]=await Promise.all([riskRegisterReadinessView(),api('/api/incident-recovery?limit=100')]);return base+incidentRecoveryPanel(recovery);};
function resilienceControlsPanel(d){return `<div class="divider"></div><section class="panel"><div class="panel-head"><h2>${tr('ضوابط المرونة','Resilience controls')}</h2></div><div class="panel-body"><div class="hint">${h(d.claim)}</div>${table([tr('النطاق والحالة','Scope / state'),tr('نسخ إعدادات الشبكة','Network configuration backups'),tr('الإدارة خارج النطاق','Out-of-band management'),tr('موصل الإدارة البديل','Alternate management connector'),tr('Playbook انقطاع محرك SOC','SOC engine outage playbook'),tr('Fail-safe للسياسات المؤقتة','Temporary-policy fail-safe'),tr('الدليل','Evidence')],d.items.map(item=>[`${h(item.control_id)}<div class="secondary">${h(item.scope)} · ${h(item.asset.hostname||item.asset.external_id)}</div>${pill(item.resilience_state)}`,`${pill(item.network_configuration_backups.status)} · ${h(label(item.network_configuration_backups.storage_separation))}<div class="secondary">${h(item.network_configuration_backups.scope||'—')} · ${item.network_configuration_backups.last_success_at?h(date(item.network_configuration_backups.last_success_at)):'—'}</div>`,`${pill(item.out_of_band_management.status)}<div class="secondary">${h(item.out_of_band_management.path_ref||'—')} · ${item.out_of_band_management.last_test_at?h(date(item.out_of_band_management.last_test_at)):'—'}</div>`,`${pill(item.alternate_management_connector.status)}<div class="secondary">${h(item.alternate_management_connector.connector_ref||'—')} · ${item.alternate_management_connector.last_test_at?h(date(item.alternate_management_connector.last_test_at)):'—'}</div>`,`${pill(item.soc_engine_outage_playbook.status)}<div class="secondary">${h(item.soc_engine_outage_playbook.playbook_ref||'—')} · ${item.soc_engine_outage_playbook.last_exercised_at?h(date(item.soc_engine_outage_playbook.last_exercised_at)):'—'}</div>`,`${pill(item.temporary_policy_fail_safe.status)} ${pill(item.temporary_policy_fail_safe.mode)}<div class="secondary">${h(item.temporary_policy_fail_safe.policy_scope||'—')} · ${h(item.temporary_policy_fail_safe.owner_id||'—')} · ${item.temporary_policy_fail_safe.expires_at?h(date(item.temporary_policy_fail_safe.expires_at)):'—'}</div>`,`${h(item.network_configuration_backups.evidence_ref||tr('لا دليل نسخ','No backup evidence'))}<br>${h(item.out_of_band_management.evidence_ref||tr('لا دليل خارج النطاق','No OOB evidence'))}<br>${h(item.alternate_management_connector.evidence_ref||tr('لا دليل موصل بديل','No alternate connector evidence'))}<br>${h(item.soc_engine_outage_playbook.evidence_ref||tr('لا دليل Playbook','No playbook evidence'))}<br>${h(item.temporary_policy_fail_safe.evidence_ref||tr('لا دليل Fail-safe','No fail-safe evidence'))}<br>${button('event',tr('دليل ضوابط المرونة','Resilience-control evidence'),item.event_id,'text-button')}`]),tr('لا توجد سجلات ضوابط مرونة','No resilience-control records'),d)}</div></section>`;}
